import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { useWithdrawalContextValue } from '../../context'
import { WITHDRAWAL_ACTIONS } from '../actions'

export const useWithdrawalServiceCall = (actionsCall = () => {}) => {
  const [withdrawalState, dispatch] = useWithdrawalContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = useCallback((payload = {}) => {
    callApi(actionsCall({
      ...payload
    }))
  }, [callApi, actionsCall])
  return [withdrawalState, request]
}

export const useGetWithdrawalList = () => {
  return useWithdrawalServiceCall(WITHDRAWAL_ACTIONS.getWithdrawalList)
}

export const useGetBankList = () => {
  return useWithdrawalServiceCall(WITHDRAWAL_ACTIONS.getBankList)
}

export const useRequestBankWithdraw = () => {
  return useWithdrawalServiceCall(WITHDRAWAL_ACTIONS.requestBankWithdraw)
}
