import { useState, useEffect, useRef } from 'react'
import { Container, CustomText, Modal, Button, InnerForm } from '../../../../../../components'
import { BankFormWrapper, WithdrawalErrorBox } from './index.style'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { formatMoney, getErrorMessage } from '../../../../../../helpers/utility'
import { NotificationContainer } from 'react-notifications'
import { BANK_LANGS } from '../../../lang'
import { MAXIMUM_WITHDRAWAL_AMOUNT } from '../../../../../../constants/payment'
import NumericInput from '../../../../../../components/NumericInput'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../../lang'
import CircularLoader from '../../../../../../components/CircularLoader'
import WarningNotifications from '../../WarningNotifications'
import { useGlobalContextValue } from '../../../../../../contextProvider/GlobalContext'
import { useRequestBankWithdraw } from '../../../state/hooks/useWithdraw'
import { useGetBankAccountList } from '../../../../Profile/Pages/BankAccount/state/hooks/useBankAccounts'
import { useLoaderContextValue, useResetError, useErrorContextValue } from '@pasarpolis/common-react-hooks'
import { useGetAgentDetails } from '../../../../../../state/globalState/hooks/useGlobalContext'
import { useHistory } from 'react-router'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import StatusInfoCard from '../../../../../../components/StatusInfoCard'

function BankFormContainer () {
  const [bankAccounts = [], getBankAccountsRequest] = useGetBankAccountList()
  const [{ bankWithdrawStatus, bankWithdrawErrorData }] = useErrorContextValue()
  const [{ BANK_WITHDRAW_LOADER }] = useLoaderContextValue()
  const [, getAgentDetailsRequest] = useGetAgentDetails()
  const [showText, setShowText] = useState(false)
  const [showWithdrawError, setShowWithdrawError] = useState(false)
  const history = useHistory()
  const [{ bankWithdrawData }, bankWithdrawRequest] = useRequestBankWithdraw()
  const { resetError } = useResetError()
  const [showAmountModal, setshowAmountModal] = useState(false)
  const [errorOnWithDrawl, seterrorOnWithDrawl] = useState('')
  const [amount, setAmount] = useState(0)
  const [values, setValues] = useState({})
  const [isTransferDisabled, setIsTransferDisabled] = useState(true)
  const [showWarning, setShowWarning] = useState(true)
  const [{ getAgentDetailData = {}, isGojekDriver, isGojekAgent }] = useGlobalContextValue()
  const inputRef = useRef()
  const bankAccountList = bankAccounts?.getBankAccountListData?.data.filter((item) => item.status === 'VERIFIED')

  useEffect(() => {
    getBankAccountsRequest()
  }, [getBankAccountsRequest])

  useEffect(() => {
    if (bankAccountList) {
      if (bankAccountList.length === 0) {
        history.push('/bank-account')
      }
    }
  }, [history, bankAccountList])
  // function getErrorMsg (bankWithdrawStatus) {
  //   const { details = {} } = bankWithdrawStatus
  //   let errorOnWithDrawl = 'Minimal 1 penjualan polis berhasil dibutuhkan untuk pencairan.'
  //   if (details.withdrawable_amount && details.current_eligible_policies) {
  //     errorOnWithDrawl = `Anda dapat mencairkan hingga ${formatMoney(details.withdrawable_amount, 0)} untuk penjualan sebanyak ${details.current_eligible_policies} polis. Jual ${details.policies_to_be_sold} polis lagi untuk mencairkan sisa ${formatMoney(details.balance_amount, 0)}!`
  //   } else if (!details.withdrawable_amount) {
  //     errorOnWithDrawl = `Jual ${details.policies_to_be_sold} polis lagi untuk mencairkan sisa ${formatMoney(details.balance_amount, 0)}!`
  //   }
  //   seterrorOnWithDrawl(errorOnWithDrawl)
  // }

  useEffect(() => {
    if (bankWithdrawStatus === 'success') {
      resetError(['bankWithdrawStatus'])
      getAgentDetailsRequest()
      history.push({
        pathname: '/balance/withdrawal/success',
        state: {
          bankWithdrawData
        }
      })
    } else if (bankWithdrawStatus || bankWithdrawErrorData) {
      if (bankWithdrawErrorData?.error_code === 'PP-AS-W-405') {
        setShowText(true)
      } if (bankWithdrawErrorData?.error_code === 'PP-AS-W-400') {
        ShowSnackbar.error({
          visible: true,
          text: getErrorMessage(500, bankWithdrawErrorData?.error_code) + bankWithdrawErrorData?.withdrawl_amount
        })
      } else {
        ShowSnackbar.error({
          visible: true,
          text: getErrorMessage(500, bankWithdrawErrorData?.error_code)
        })
      }
      resetError(['bankWithdrawStatus', 'bankWithdrawErrorData'])
    }
  }, [
    bankWithdrawStatus, history, resetError,
    getAgentDetailsRequest, bankWithdrawErrorData,
    bankWithdrawData
  ])

  const handleAmountChange = e => {
    const walletBalance = Math.floor(getAgentDetailData?.wallet_balance)
    if ((e <= walletBalance) || !e) {
      let disableTransferBtn = true
      if (e && e <= walletBalance) {
        disableTransferBtn = false
        setShowWithdrawError(false)
      }
      setAmount(e)
      setIsTransferDisabled(disableTransferBtn)
    }
    setShowText(false)
  }

  const handleFormSubmit = (values) => {
    setValues(values)
    setshowAmountModal(true)
    seterrorOnWithDrawl('')
  }

  const handleToCloseWarning = () => {
    setShowWarning(false)
  }

  const handleCloseModal = () => {
    setshowAmountModal(false)
    setAmount(0)
    setShowText(false)
  }

  const handleSubmit = () => {
    const walletBalance = Math.floor(getAgentDetailData?.wallet_balance)
    if (amount < 0 || (walletBalance - amount < 0)) {
      ShowSnackbar.error({
        visible: true,
        text: ERROR_LANG.incorrectAmountEntered
      })
    } else if (amount > MAXIMUM_WITHDRAWAL_AMOUNT) {
      // setShowText(true)
      ShowSnackbar.error({
        visible: true,
        text: 'Anda tidak bisa menarik komisi lebih dari Rp. 50.000.000 dalam sekali penarikan transaksi'
      })
    } else {
      const finalData = { ...values, amount }
      delete finalData.errorField
      bankWithdrawRequest(finalData)
    }
  }

  const formData = {
    fields: [
      {
        type: 'select',
        name: 'bank_id',
        placeholder: 'Pilih Nomor Rekening',
        label: 'Pilih Nomor Rekening',
        data: bankAccountList,
        dataKey: 'id',
        displayKey: 'holder_id',
        defaultValue: bankAccountList?.id
      }],
    buttons: [{
      type: 'submit',
      text: 'SELANJUTNYA',
      className: 'btn-margin-top'
    }]
  }

  return (
    <Container
      title='Tarik Saldo'
      className='bg-white'
    >
      <BankFormWrapper>
        {
          (showWarning) &&
        (
          <WarningNotifications
            onClose={handleToCloseWarning}
            className='warning'
          />
        )
        }
        <CustomText color={AgentColorPallette.black} size='16px' weight={800} bottom='16px'>
          {'Transfer Ke Rekening Bank'}
        </CustomText>
        <InnerForm
          formData={formData}
          onSubmit={handleFormSubmit}
        />
        <br />
        {/* <StatusInfoCard
          info={<span>Informasi penarikan saldo: <br /> 1. Limit transfer per transaksi adalah Rp 25.000.000 <br /> 2. Limit transfer per minggu adalah Rp 30.000.000</span>}
        /> */}
        {/* <TaxStyleBox>
          {BANK_LANGS.incomeTaxArticle}
        </TaxStyleBox> */}
        <Modal heading='Transfer ke Bank' isOpen={showAmountModal} onClose={handleCloseModal}>
          <CircularLoader isLoading={BANK_WITHDRAW_LOADER}>
            <BankFormWrapper padding='0'>
              {
                (isGojekAgent || isGojekDriver) && (
                  <CustomText
                    color={AgentColorPallette.errorDark}
                    size='11px'
                    bottom='18px'
                    weight='700'
                  >
                    {LANG_STRINGS.withdrawalAmountNotify}
                  </CustomText>
                )
              }
              <CustomText color={AgentColorPallette.black} size='14px' weight='700'>
                {'Masukan Jumlah'}
              </CustomText>
              <div className='row-space-between'>
                <CustomText color={AgentColorPallette.fontDarkerGrey}>
                  {'Saldo saya'}
                </CustomText>
                <CustomText color={AgentColorPallette.fontDarkerGrey} weight={700}>
                  {formatMoney(Math.floor(getAgentDetailData?.wallet_balance), 0)}
                </CustomText>
              </div>
              <br />
              <div className='row-space-between'>
                <CustomText color={AgentColorPallette.errorDark}>
                  {'Transfer sebesar'}
                </CustomText>
                &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;
                <div className='amount-row'>
                  <CustomText color={AgentColorPallette.errorDark}>
                    {'- '}
                  </CustomText>
                  <NumericInput
                    ref={inputRef}
                    value={amount}
                    name='amount'
                    type='amount'
                    onChange={handleAmountChange}
                    id='withdrawalAmount'
                    className='input'
                    wrapperClass='inputWrapepr'
                    isSkipRegex
                    placeholder={LANG_STRINGS.enterAmount}
                  />
                </div>
              </div>
              {/* {
                showWithdrawError &&
                  <WithdrawalErrorBox>
                    <div className='info-message'>
                      {BANK_LANGS.withdrawalLimit}
                    </div>
                  </WithdrawalErrorBox>
              } */}
              {
                showText &&
                  <CustomText
                    fontWeight={700}
                    fontSize='0.7em'
                    fontColor={AgentColorPallette.vibrantRed}
                  >
                    {getErrorMessage(500, 'PP-AS-W-405')}
                  </CustomText>
              }
              {/* <CustomText
                fontWeight={400}
                fontSize='0.7em'
                fontColor={AgentColorPallette.black}
              >
                *Anda tidak bisa menarik komisi lebih dari <br /> Rp. 25.000.000 dalam sekali penarikan transaksi
              </CustomText> */}
              {
                isGojekDriver && errorOnWithDrawl && (
                  <CustomText
                    color={AgentColorPallette.errorDark}
                    size='11px'
                    bottom='18px'
                    top='10px'
                    weight='700'
                  >
                    {errorOnWithDrawl}
                  </CustomText>
                )
              }
              <hr />
              <div className='row-space-between'>
                <CustomText color={AgentColorPallette.fontDarkerGrey}>
                  {'Saldo akhir'}
                </CustomText>
                <CustomText color={AgentColorPallette.fontDarkerGrey} weight={700}>
                  {formatMoney(Math.floor(getAgentDetailData?.wallet_balance) - amount, 0)}
                </CustomText>
              </div>
              <hr />
              <div className='row-space-between'>
                <Button className='button-width back' onClick={handleCloseModal}>BATAL</Button>
                <Button disabled={isTransferDisabled} className='button-width' onClick={handleSubmit}>TRANSFER</Button>
              </div>
            </BankFormWrapper>
          </CircularLoader>
        </Modal>
        <NotificationContainer />
      </BankFormWrapper>
    </Container>
  )
}

export default BankFormContainer
